class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        if len(s) != len(t):
            return False
        rest = list(t)
        for ch in s:
            for i, other in enumerate(rest):
                if ch == other:
                    rest.pop(i)
                    break
            else:
                return False
        return not rest

